export function applyLeaves(dst,w,h,cam,registration,phase,enabled){if(!enabled||phase===0)return 0;const src=dst.slice();let count=0;for(let ri=0;ri<registration.regions.length;ri++){const region=registration.regions[ri];for(const[x,y,weight]of region.points){const xx=x-cam[0],yy=y-cam[1];if(xx<2||yy<2||xx>=w-2||yy>=h-2)continue;const shift=registration.maxShiftPx*Math.sin(phase*Math.PI*2/48)*Math.sin((y-region.ellipse[1])/24+ri*.7);const sx=xx+shift,ix=Math.floor(sx),f=sx-ix;const at=(yy*w+xx)*4,left=(yy*w+ix)*4;for(let c=0;c<3;c++)dst[at+c]=Math.round(src[at+c]*(1-weight)+(src[left+c]*(1-f)+src[left+4+c]*f)*weight);count++;}}return count}
export function drawLampGlow(ctx,cam,registration,night){if(night<=0)return 0;ctx.save();ctx.globalCompositeOperation='screen';let count=0;for(const[x,y]of registration.lampsVisualCandidates){const a=x-cam[0],b=y-cam[1];if(a< -80||b< -80||a>1040||b>620)continue;const g=ctx.createRadialGradient(a,b,2,a,b,68);g.addColorStop(0,`rgba(255,204,106,${.55*night})`);g.addColorStop(.33,`rgba(255,176,69,${.19*night})`);g.addColorStop(1,'rgba(255,150,45,0)');ctx.fillStyle=g;ctx.fillRect(a-68,b-68,136,136);count++;}ctx.restore();return count}
